#!/bin/sh
for _a in "$@"; do case "$_a" in --help|-h)
	printf 'usage: %s\n' "${0##*/}"
	printf '%s\n' 'Symlink the standard dotfiles (aliases, Xresources, ghostty, foot) into the home directory; takes no arguments.'
	exit 0;; esac; done
# >>> shguard modes=exec (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'link.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  exec) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: exec; pipe callers set SHGUARD_MODE=pipe)\n' 'link.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
_bid="$(dirname "$(realpath "$0")")/util/lib/build-id.sh"
# shellcheck source=util/lib/build-id.sh
[ -r "$_bid" ] && { . "$_bid"; build_flags "$0" "$@"; }
set -eu

# link.sh: create the standard dotfile symlinks into $HOME.
#
# CC0: This work has been marked as dedicated to the public domain.
# https://creativecommons.org/publicdomain/zero/1.0/

here=$(dirname "$(realpath "$0")")

# aliases load on every shell (~/.bash_aliases is sourced by ~/.bashrc)
rm -f "$HOME/.bash_aliases"
ln -s "$here/aliases.sh" "$HOME/.bash_aliases"

# X resources (terminal colors / theme); merged via the `xres` alias
rm -f "$HOME/.Xresources"
ln -s "$here/Xresources" "$HOME/.Xresources"

# ghostty terminal config (canonical name is `config`, not `config.ghostty`)
mkdir -p "$HOME/.config/ghostty"
ln -sfn "$here/ghostty/config" "$HOME/.config/ghostty/config"

# foot terminal config (CDE's default terminal; ghostty stays as the rollback)
mkdir -p "$HOME/.config/foot"
ln -sfn "$here/foot/foot.ini" "$HOME/.config/foot/foot.ini"
